CREATE TRIGGER work_sync_project_i AFTER INSERT ON work_projects BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'projects',NEW.id,'upsert',json_object('id',NEW.id,'code',NEW.code,'name',NEW.name,'status',NEW.status,'priority',NEW.priority,'progress',NEW.progress,'dueDate',NEW.due_date)); END;
CREATE TRIGGER work_sync_project_u AFTER UPDATE ON work_projects BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'projects',NEW.id,CASE WHEN NEW.archived_at IS NULL THEN 'upsert' ELSE 'delete' END,CASE WHEN NEW.archived_at IS NULL THEN json_object('id',NEW.id,'code',NEW.code,'name',NEW.name,'status',NEW.status,'priority',NEW.priority,'progress',NEW.progress,'dueDate',NEW.due_date) END); END;
CREATE TRIGGER work_sync_task_i AFTER INSERT ON work_tasks WHEN NOT EXISTS(SELECT 1 FROM work_mobile_sync_suppression WHERE record_key=NEW.organization_id||':tasks:'||NEW.id) BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'tasks',NEW.id,'upsert',json_object('id',NEW.id,'taskNumber',NEW.task_number,'projectId',NEW.project_id,'title',NEW.title,'status',NEW.status,'priority',NEW.priority,'dueAt',NEW.due_at,'completedAt',NEW.completed_at,'actualMinutes',NEW.actual_minutes,'progress',NEW.progress)); END;
CREATE TRIGGER work_sync_task_u AFTER UPDATE ON work_tasks WHEN NOT EXISTS(SELECT 1 FROM work_mobile_sync_suppression WHERE record_key=NEW.organization_id||':tasks:'||NEW.id) BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'tasks',NEW.id,CASE WHEN NEW.archived_at IS NULL THEN 'upsert' ELSE 'delete' END,CASE WHEN NEW.archived_at IS NULL THEN json_object('id',NEW.id,'taskNumber',NEW.task_number,'projectId',NEW.project_id,'title',NEW.title,'status',NEW.status,'priority',NEW.priority,'dueAt',NEW.due_at,'completedAt',NEW.completed_at,'actualMinutes',NEW.actual_minutes,'progress',NEW.progress) END); END;
CREATE TRIGGER work_sync_check_i AFTER INSERT ON work_task_checklist_items BEGIN INSERT INTO work_mobile_change_events SELECT NULL,t.organization_id,'checklist-items',NEW.id,'upsert',json_object('id',NEW.id,'taskId',NEW.task_id,'title',NEW.title,'isCompleted',NEW.is_completed,'position',NEW.position,'completedBy',NEW.completed_by,'completedAt',NEW.completed_at) FROM work_tasks t WHERE t.id=NEW.task_id; END;
CREATE TRIGGER work_sync_check_u AFTER UPDATE ON work_task_checklist_items BEGIN INSERT INTO work_mobile_change_events SELECT NULL,t.organization_id,'checklist-items',NEW.id,'upsert',json_object('id',NEW.id,'taskId',NEW.task_id,'title',NEW.title,'isCompleted',NEW.is_completed,'position',NEW.position,'completedBy',NEW.completed_by,'completedAt',NEW.completed_at) FROM work_tasks t WHERE t.id=NEW.task_id; END;
CREATE TRIGGER work_sync_check_d AFTER DELETE ON work_task_checklist_items BEGIN INSERT INTO work_mobile_change_events SELECT NULL,t.organization_id,'checklist-items',OLD.id,'delete',NULL FROM work_tasks t WHERE t.id=OLD.task_id; END;
CREATE TRIGGER work_sync_comment_i AFTER INSERT ON work_comments WHEN NOT EXISTS(SELECT 1 FROM work_mobile_sync_suppression WHERE record_key=NEW.organization_id||':comments:'||NEW.id) BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'comments',NEW.id,'upsert',json_object('id',NEW.id,'taskId',NEW.task_id,'authorUserId',NEW.author_user_id,'body',NEW.body,'mentions',json(NEW.mentions_json),'createdAt',NEW.created_at)); END;
CREATE TRIGGER work_sync_comment_u AFTER UPDATE ON work_comments WHEN NOT EXISTS(SELECT 1 FROM work_mobile_sync_suppression WHERE record_key=NEW.organization_id||':comments:'||NEW.id) BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'comments',NEW.id,CASE WHEN NEW.deleted_at IS NULL THEN 'upsert' ELSE 'delete' END,CASE WHEN NEW.deleted_at IS NULL THEN json_object('id',NEW.id,'taskId',NEW.task_id,'authorUserId',NEW.author_user_id,'body',NEW.body,'mentions',json(NEW.mentions_json),'createdAt',NEW.created_at) END); END;
CREATE TRIGGER work_sync_time_i AFTER INSERT ON work_time_entries WHEN NOT EXISTS(SELECT 1 FROM work_mobile_sync_suppression WHERE record_key=NEW.organization_id||':time-entries:'||NEW.id) BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'time-entries',NEW.id,'upsert',json_object('id',NEW.id,'taskId',NEW.task_id,'userId',NEW.user_id,'description',NEW.description,'startedAt',NEW.started_at,'endedAt',NEW.ended_at,'minutes',NEW.minutes,'billable',NEW.billable)); END;
CREATE TRIGGER work_sync_time_u AFTER UPDATE ON work_time_entries WHEN NOT EXISTS(SELECT 1 FROM work_mobile_sync_suppression WHERE record_key=NEW.organization_id||':time-entries:'||NEW.id) BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,NEW.organization_id,'time-entries',NEW.id,'upsert',json_object('id',NEW.id,'taskId',NEW.task_id,'userId',NEW.user_id,'description',NEW.description,'startedAt',NEW.started_at,'endedAt',NEW.ended_at,'minutes',NEW.minutes,'billable',NEW.billable)); END;
CREATE TRIGGER work_sync_time_d AFTER DELETE ON work_time_entries BEGIN INSERT INTO work_mobile_change_events VALUES(NULL,OLD.organization_id,'time-entries',OLD.id,'delete',NULL); END;
